请对以下 case 进行三维加权评分。

=== case_id ===
Case-16-travel-ticket-006

=== 用户原始指令 (query.txt) ===
帮我弄个航班卡 一点能跳到app那种

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个航班卡 一点能跳到app那种",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "flight": {
      "flightNo": {
        "type": "string",
        "description": "航班号展示文本",
        "sampleValue": "CZ3125 航班"
      },
      "routeTitle": {
        "type": "string",
        "description": "航班出发城市到到达城市的短路线",
        "sampleValue": "深圳-北京"
      },
      "departTime": {
        "type": "string",
        "description": "计划起飞时间展示文本",
        "sampleValue": "13:20"
      },
      "arriveTime": {
        "type": "string",
        "description": "计划到达时间展示文本",
        "sampleValue": "16:35"
      },
      "statusText": {
        "type": "string",
        "description": "航班状态与日期摘要",
        "sampleValue": "准点 今天"
      },
      "gateLabel": {
        "type": "string",
        "description": "登机口标签",
        "sampleValue": "登机口"
      },
      "gate": {
        "type": "string",
        "description": "登机口编号",
        "sampleValue": "B12"
      },
      "seatLabel": {
        "type": "string",
        "description": "座位标签",
        "sampleValue": "座位"
      },
      "seat": {
        "type": "string",
        "description": "座位号",
        "sampleValue": "12A"
      },
      "actionLabel": {
        "type": "string",
        "description": "打开详情入口的短按钮文案",
        "sampleValue": "查看详情"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/airplane_departure.svg",
      "description": "飞机起飞图标，黑色线性图形，适合用于航班行程和出发信息的识别。"
    }
  ]
}

